"""Illustrative sample strategy. Not generated by a live Vibe-Trading run."""

class SignalEngine:
    def generate(self, data):
        frame = data["AAPL"]
        fast = frame["close"].rolling(20).mean()
        slow = frame["close"].rolling(50).mean()
        return (fast > slow).astype(float).to_frame("AAPL")
